var libCode = local('crypto');
new Function(libCode)();
var file = local('file');
var key = local('key');

function decryptText(cipher, key) {
    if (!cipher) return '';
    var parts = cipher.split('::');
    if (cipher.indexOf('U2FsdGVkX1') !== 0 || !/::[0-9a-fA-F]{64}$/.test(cipher)) {
        return cipher;
    }
    var encryptedPart = parts[0];
    var hmacPart = parts[1];
    var expectedHmac = CryptoJS.HmacSHA256(encryptedPart, key).toString();
    if (expectedHmac !== hmacPart) return '[HMAC校验失败]';
    try {
        var bytes = CryptoJS.AES.decrypt(encryptedPart, key);
        return bytes.toString(CryptoJS.enc.Utf8);
    } catch (e) {
        return '[解密失败]';
    }
}

var content = readFile(file);
if (content === undefined || content === null || content === 'undefined') {
    content = '';
}

var plainText = content;
if (key && key.length > 0 && content.indexOf('U2FsdGVkX1') === 0) {
    plainText = decryptText(content, key);
}
setLocal('clip', plainText);

var libCode = local('crypto');
new Function(libCode)(); 

var par1 = local('par1');
var key = local('key');
var baseDir = local('dir') + '/';

var lastDot = par1.lastIndexOf('.');
var basePath = par1.substring(0, lastDot);
var splitStr = par1.substring(lastDot + 1);
var splitMax = parseInt(splitStr);
if (isNaN(splitMax)) {
    splitMax = 0;
    basePath = par1;
}

var absBase = baseDir + basePath; 
var filePaths = [];
if (splitMax > 0) {
    for (var i = 1; i <= splitMax; i++) {
        filePaths.push(absBase + '.' + i);
    }
} else {
    filePaths.push(absBase);
}

function escapeSpecialChars(str) {
    return str.replace(/([()\[\],\\])/g, '\\$1');
}

function decryptText(cipher, key) {
    if (!cipher) return '';
    var parts = cipher.split('::');
    if (cipher.indexOf('U2FsdGVkX1') !== 0 || !/::[0-9a-fA-F]{64}$/.test(cipher)) {
        return cipher;
    }
    var encryptedPart = parts[0];
    var hmacPart = parts[1];
    var expectedHmac = CryptoJS.HmacSHA256(encryptedPart, key).toString();
    if (expectedHmac !== hmacPart) return '[HMAC校验失败]';
    try {
        var bytes = CryptoJS.AES.decrypt(encryptedPart, key);
        return bytes.toString(CryptoJS.enc.Utf8);
    } catch (e) {
        return '[解密失败]';
    }
}

var writeCommands = [];
for (var idx = 0; idx < filePaths.length; idx++) {
    var content = readFile(filePaths[idx]);
    if (content === undefined || content === null || content === 'undefined') {
        content = '';
    }

    var plainText = content;
    if (key && key.length > 0) {
        if (content.indexOf('U2FsdGVkX1') === 0) {
            plainText = decryptText(content, key);
        }
    }

    var escaped = escapeSpecialChars(plainText);
    writeCommands.push('write(' + escaped + ')');
}

var result = writeCommands.join(',');

setLocal('input', result);

