mac = javax.crypto.Mac.getInstance("HmacSHA256");
mac.init(new javax.crypto.spec.SecretKeySpec(key.getBytes("UTF-8"), "HmacSHA256"));
hmacBytes = mac.doFinal(encryptedPart.getBytes("UTF-8"));
expectedHmac = java.lang.String.format("%064x", new java.math.BigInteger(1, hmacBytes));
if (!expectedHmac.equals(hmacPart)) {
