}

allBytes = android.util.Base64.decode(encryptedPart, android.util.Base64.NO_WRAP);

if (allBytes.length < 16 || allBytes[0] != 0x53 || allBytes[1] != 0x61 || allBytes[2] != 0x6c || allBytes[3] != 0x74 || allBytes[4] != 0x65 || allBytes[5] != 0x64 || allBytes[6] != 0x5f || allBytes[7] != 0x5f) {
