passwordBytes = key.getBytes("UTF-8");
totalLen = 48;
out = new java.io.ByteArrayOutputStream();
prev = null;
md = java.security.MessageDigest.getInstance("MD5");
while (out.size() < totalLen) {
    input = new java.io.ByteArrayOutputStream();
    if (prev != null) {
        input.write(prev);
    }
    input.write(passwordBytes);
    input.write(salt);
    digest = md.digest(input.toByteArray());
    out.write(digest);
    prev = digest;
}
derived = out.toByteArray();
aesKey = java.util.Arrays.copyOfRange(derived, 0, 32);
iv = java.util.Arrays.copyOfRange(derived, 32, 48);

cipherObj = javax.crypto.Cipher.getInstance("AES/CBC/PKCS5Padding");
cipherObj.init(javax.crypto.Cipher.DECRYPT_MODE, new javax.crypto.spec.SecretKeySpec(aesKey, "AES"), new javax.crypto.spec.IvParameterSpec(iv));
decryptedBytes = cipherObj.doFinal(encryptedBytes);

new java.lang.String(decryptedBytes, "UTF-8");",
